import java.io.*;
import java.net.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.xml.parsers.*;
import org.xml.sax.*;
import org.xml.sax.helpers.DefaultHandler;
import org.w3c.dom.*;
import java.util.logging.*;

public class WebhookReceiverServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("WebhookReceiver");
    private DocumentBuilderFactory dbf;

    @Override
    public void init() throws ServletException {
        dbf = DocumentBuilderFactory.newInstance();
        // Developer attempted to harden but only disabled DTD validation
        // not external entity resolution
        try {
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        } catch (ParserConfigurationException e) {
            log.warning("Could not configure parser features: " + e.getMessage());
        }
        // Note: setExpandEntityReferences(false) does NOT prevent XXE
        // it only affects whether entity refs are expanded in the DOM tree
        dbf.setExpandEntityReferences(false);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String contentType = req.getContentType();
        if (contentType == null || !contentType.contains("application/xml")) {
            resp.sendError(415, "Unsupported Media Type");
            return;
        }

        // Validate webhook signature
        String signature = req.getHeader("X-Webhook-Signature");
        if (signature == null || signature.length() < 32) {
            resp.sendError(401, "Invalid signature");
            return;
        }

        try {
            DocumentBuilder db = dbf.newDocumentBuilder();
            // Parse the incoming XML webhook payload
            Document doc = db.parse(req.getInputStream());
            doc.getDocumentElement().normalize();

            String rootTag = doc.getDocumentElement().getTagName();
            if (!"webhook-event".equals(rootTag)) {
                resp.sendError(400, "Invalid root element");
                return;
            }

            // Extract event data
            NodeList eventNodes = doc.getElementsByTagName("event-type");
            NodeList dataNodes = doc.getElementsByTagName("payload");

            if (eventNodes.getLength() == 0) {
                resp.sendError(400, "Missing event-type");
                return;
            }

            String eventType = eventNodes.item(0).getTextContent();
            String payload = dataNodes.getLength() > 0 ?
                dataNodes.item(0).getTextContent() : "";

            log.info("Received webhook: type=" + eventType);

            // Process based on event type
            switch (eventType) {
                case "order.created":
                case "order.updated":
                case "order.cancelled":
                    processOrderEvent(eventType, payload, resp);
                    break;
                case "inventory.low":
                    processInventoryAlert(payload, resp);
                    break;
                default:
                    resp.sendError(400, "Unknown event type: " + eventType);
                    return;
            }
        } catch (ParserConfigurationException | SAXException e) {
            log.severe("XML parsing error: " + e.getMessage());
            resp.sendError(400, "Malformed XML");
        }
    }

    private void processOrderEvent(String type, String data, HttpServletResponse resp)
            throws IOException {
        resp.setStatus(200);
        resp.getWriter().write("{\"status\":\"processed\",\"type\":\"" + type + "\"}");
    }

    private void processInventoryAlert(String data, HttpServletResponse resp)
            throws IOException {
        resp.setStatus(200);
        resp.getWriter().write("{\"status\":\"alert_received\"}");
    }
}
